// Turns the hg_settings rows (key/value) into one config object for this run.
const cfg = {};
for (const item of $input.all()) {
  if (item.json && item.json.key) cfg[item.json.key] = item.json.value;
}
if (!cfg.openai_model) throw new Error('hg_settings is empty: run supabase/schema.sql and scripts/setup.py supabase');
cfg.today = new Date().toISOString().slice(0, 10);
return [{ json: cfg }];

// Receives {file_name, mime_type, data_base64} and turns it into an n8n binary file.
const body = $('Webhook').first().json.body || {};
const fileName = String(body.file_name || 'unnamed').replace(/[\\/]/g, '_').slice(0, 200);
const b64 = String(body.data_base64 || '').replace(/^data:[^,]*,/, '').replace(/\s/g, '');
const ext = fileName.indexOf('.') === -1 ? '' : fileName.split('.').pop().toLowerCase();
const mimeMap = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
};
const mime = body.mime_type || mimeMap[ext] || 'application/octet-stream';
const size = Math.floor(b64.length * 3 / 4);

const json = { file_name: fileName, ext: b64 ? ext : 'missing', mime: mime, size: size, source: body.source || 'upload' };
if (size > 15 * 1024 * 1024) json.ext = 'too_big';
if (json.ext === 'pdf') json.b64 = b64; // kept for the OCR fallback
const binary = b64 ? { data: { data: b64, mimeType: mime, fileName: fileName, fileExtension: ext } } : {};
return [{ json: json, binary: binary }];

// Output of "Extract from File (PDF)". A broken PDF arrives here as an error item (node continues on error).
const j = $input.first().json || {};
const err = j.error ? (j.error.message || String(j.error)) : '';
return [{ json: { text: j.text || '', method: 'text', reason: err ? 'PDF could not be opened: ' + err.slice(0, 150) : '' } }];

// A .docx is a zip. "Unzip DOCX" gave us its files; read word/document.xml and strip the XML.
const item = $input.first();
const bin = item.binary || {};
let key = null;
for (const k of Object.keys(bin)) {
  const name = String(bin[k].fileName || '').toLowerCase();
  const dir = String(bin[k].directory || '').toLowerCase();
  if (/(^|\/)document\.xml$/.test(name) && name.indexOf('glossary') === -1 && dir.indexOf('glossary') === -1) {
    key = k;
    if ((dir + '/' + name).indexOf('word') !== -1) break;
  }
}
if (!key) {
  const err = item.json && item.json.error ? ' (' + (item.json.error.message || item.json.error) + ')' : '';
  return [{ json: { text: '', method: 'text', reason: 'Not a valid Word file: word/document.xml missing' + err } }];
}
const buf = await this.helpers.getBinaryDataBuffer(0, key);
let xml = buf.toString('utf8');
xml = xml.replace(/<w:tab\/>/g, '\t').replace(/<w:br[^>]*\/>/g, '\n').replace(/<\/w:p>/g, '\n').replace(/<\/w:tc>/g, '\t');
const text = xml.replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'");
return [{ json: { text: text, method: 'text', reason: '' } }];

// Anything that is not PDF/DOCX ends up here and is flagged (never silently skipped).
const f = $('Prepare File').first().json;
const why = {
  missing: 'The upload contained no file data',
  too_big: 'File is larger than 15 MB'
}[f.ext] || ('Unsupported file type ".' + (f.ext || '?') + '" (send PDF or DOCX)');
return [{ json: { text: '', method: 'none', reason: why } }];

// Decides: is there enough text? If not and it is a PDF, try OCR (scanned CV).
const f = Object.assign({}, $('Prepare File').first().json);
delete f.b64;
const j = $input.first().json;
const text = String(j.text || '').replace(/\u0000/g, '').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const letters = (text.match(/[A-Za-z؀-ۿ]/g) || []).length;
const readable = letters >= 150;
return [{
  json: Object.assign(f, {
    text: text,
    method: j.method || 'text',
    letters: letters,
    readable: readable,
    needs_ocr: !readable && f.ext === 'pdf',
    reason: readable ? '' : (j.reason || 'No readable text found in the file')
  })
}];

// Scanned / image-only PDF: send the PDF to the OpenAI vision model and ask for a transcription.
const j = $input.first().json;
const cfg = $('Config').first().json;
const b64 = $('Prepare File').first().json.b64;
return [{
  json: Object.assign({}, j, {
    openai_body: {
      model: cfg.openai_model,
      temperature: 0,
      messages: [{
        role: 'user',
        content: [
          { type: 'file', file: { filename: j.file_name, file_data: 'data:application/pdf;base64,' + b64 } },
          { type: 'text', text: 'This is a CV (resume), probably a scanned image. Transcribe ALL of its text exactly as written, ' +
            'line by line, as plain text. Do not summarise, translate or add anything. ' +
            'If the pages contain no readable CV text, reply with exactly: UNREADABLE' }
        ]
      }]
    }
  })
}];

// Result of the OCR attempt. Still no text → it will be flagged as unreadable.
const prev = Object.assign({}, $('Check Text').first().json);
const r = $input.first().json || {};
let text = '';
let reason = '';
if (r.error) {
  reason = 'OCR failed: ' + String(r.error.message || JSON.stringify(r.error)).slice(0, 200);
} else {
  text = String((((r.choices || [])[0] || {}).message || {}).content || '').trim();
}
if (/^\W*UNREADABLE\W*$/i.test(text)) {
  reason = 'Scanned file has no readable CV text (OCR found nothing)';
  text = '';
}
const letters = (text.match(/[A-Za-z؀-ۿ]/g) || []).length;
if (!reason && letters < 150) reason = 'Too little text even after OCR (' + letters + ' letters)';
return [{
  json: Object.assign(prev, {
    text: letters >= 150 ? text : '',
    method: 'ocr',
    letters: letters,
    readable: letters >= 150 && !reason,
    reason: reason
  })
}];

// Asks OpenAI to pull a structured profile out of the CV text (skills with years, languages, CV date).
const j = $input.first().json;
const cfg = $('Config').first().json;
const nstr = { type: ['string', 'null'] };
const schema = {
  type: 'object', additionalProperties: false,
  required: ['full_name', 'email', 'phone', 'location', 'timezone', 'headline', 'total_years', 'languages', 'skills', 'cv_date', 'summary'],
  properties: {
    full_name: { type: 'string' },
    email: nstr, phone: nstr, location: nstr,
    timezone: Object.assign({ description: 'IANA timezone guessed from location, e.g. Asia/Beirut' }, nstr),
    headline: { type: 'string' },
    total_years: { type: ['number', 'null'] },
    languages: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['language', 'level'],
      properties: { language: { type: 'string' }, level: { type: 'string' } } } },
    skills: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['name', 'years'],
      properties: { name: { type: 'string' }, years: { type: ['number', 'null'] } } } },
    cv_date: Object.assign({ description: 'YYYY-MM' }, nstr),
    summary: { type: 'string' }
  }
};
const system = [
  'You extract facts from a CV. Use ONLY what is written. Today is ' + cfg.today + '.',
  'Skills: list every tool/skill. Use canonical names: "GoHighLevel" (for GHL, HighLevel, Go High Level), "QuickBooks Online" (QBO),',
  '"QuickBooks Desktop", "n8n", "Zapier", "Make" (Make.com/Integromat), "React", "Node.js", "TypeScript", "AWS", "Xero", "Gusto",',
  '"Salesforce", "HubSpot", "Cold calling", "Appointment setting", "Transaction coordination", "Calendar management".',
  'Skill years: if the CV states a number for that skill (e.g. "5 years of GoHighLevel", "2.5 years"), use that number.',
  'Otherwise add up the durations of the jobs where the skill was clearly used ("Present" = today). Round to 1 decimal. null if unknown.',
  'Languages: one entry per language with the level as written (native, fluent, C1, intermediate, basic...).',
  'cv_date: an explicit "last updated" / "updated" date if the CV has one; otherwise the most recent month/year that appears',
  'as a job start or end date (ignore the word "Present"). Format YYYY-MM. null if no dates.',
  'email: lowercase. total_years: total professional experience.'
].join('\n');
return [{
  json: Object.assign({}, j, {
    openai_body: {
      model: cfg.openai_model,
      temperature: 0,
      response_format: { type: 'json_schema', json_schema: { name: 'cv_profile', strict: true, schema: schema } },
      messages: [{ role: 'system', content: system }, { role: 'user', content: 'CV TEXT:\n"""\n' + j.text.slice(0, 20000) + '\n"""' }]
    }
  })
}];

// Profile → searchable chunks. Chunk 0 is a compact profile card, then the raw CV text in overlapping pieces.
const prev = Object.assign({}, $('Profile Prompt').first().json);
delete prev.openai_body;
const cfg = $('Config').first().json;
let p;
try {
  p = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error('Profile extraction failed for ' + prev.file_name + ': ' + JSON.stringify($input.first().json).slice(0, 300));
}
const langs = (p.languages || []).map(l => l.language + ' (' + l.level + ')').join(', ');
const skills = (p.skills || []).map(s => s.name + (s.years != null ? ' ' + s.years + ' yrs' : '')).join(', ');
const chunks = [
  p.full_name + ' | ' + p.headline + ' | Location: ' + (p.location || '?') + ' | Languages: ' + langs +
  ' | Skills: ' + skills + ' | ' + p.summary
];
const text = prev.text;
const size = 1200;
const overlap = 200;
for (let i = 0; i < text.length && chunks.length < 9; i += size - overlap) chunks.push(text.slice(i, i + size));
return [{ json: Object.assign(prev, { profile: p, chunks: chunks, embed_body: { model: cfg.embedding_model, input: chunks } }) }];

// Joins chunks with their embeddings into one payload for hg_ingest_cv (dedup + replace logic lives in SQL).
const prev = $('Profile & Chunks').first().json;
const emb = $input.first().json;
const vectors = (emb.data || []).slice().sort((a, b) => a.index - b.index).map(d => d.embedding);
if (vectors.length !== prev.chunks.length) {
  throw new Error('Embedding count mismatch for ' + prev.file_name + ': ' + JSON.stringify(emb).slice(0, 200));
}
return [{
  json: {
    p: {
      file_name: prev.file_name,
      file_type: prev.ext,
      raw_text: prev.text,
      extraction_method: prev.method,
      profile: prev.profile,
      chunks: prev.chunks.map((c, i) => ({ content: c, embedding: vectors[i] }))
    }
  }
}];

// Tell the channel when an updated CV replaced an old one (duplicates are only logged).
const r = $input.first().json;
const cfg = $('Config').first().json;
const file = $('Profile & Chunks').first().json.file_name;
let text = '';
if (r.action === 'replaced') {
  text = '🔁 *Updated CV:* ' + r.name + ' sent a newer CV. `' + r.old_file + '` was replaced by `' + file +
    '`. Search now uses the new CV only.';
}
return [{ json: { notify: !!text, body: { channel: cfg.slack_channel_id, text: text } } }];

// Builds the "flag as unreadable" DB payload and the Slack alert.
const j = $input.first().json;
const cfg = $('Config').first().json;
const link = cfg.portal_url ? '\n<' + cfg.portal_url + '/cvs.html|Open CV health page>' : '';
return [{
  json: {
    p: {
      file_name: j.file_name,
      file_type: j.ext,
      raw_text: String(j.text || '').slice(0, 2000),
      extraction_method: j.method,
      unreadable: true,
      unreadable_reason: j.reason || 'No readable text found'
    },
    slack: {
      channel: cfg.slack_channel_id,
      text: '⚠️ *Unreadable CV flagged:* `' + j.file_name + '`\nReason: ' + (j.reason || 'No readable text found') +
        '\nThis CV is NOT searchable. Please ask the candidate for a text PDF or Word file.' + link
    }
  }
}];
